import { Kafka } from 'kafkajs';

const kafka = new Kafka({ brokers: ['kafka-broker-1:9092', 'kafka-broker-2:9092'] });
const admin = kafka.admin();

export async function provisionTopic(topicName: string) {
  await admin.connect();
  await admin.createTopics({
    topics: [{
      topic: topicName,
      numPartitions: 12,        // Scaled to match target consumer concurrency
      replicationFactor: 3,    // Multi-AZ fault tolerance
      configEntries: [
        { name: 'cleanup.policy', value: 'delete' },
        { name: 'retention.ms', value: '604800000' }, // 7 Days retention
        { name: 'min.insync.replicas', value: '2' },   // Enforce durable consensus
      ]
    }]
  });
  await admin.disconnect();
}
